  'tips.bookToursA': { en: 'Reception can help you book:', vi: 'Lễ tân có thể giúp bạn đặt:', zh: '前台可以帮您预订：', ko: '리셉션에서 예약을 도와드립니다:', ru: 'На стойке регистрации вам помогут забронировать:' },
