  'tips.faqTaxi': { en: '🚕 Can you help me book a taxi?', vi: '🚕 Bạn có thể giúp tôi đặt taxi không?', zh: '🚕 你能帮我预订出租车吗？', ko: '🚕 택시 예약을 도와주실 수 있나요?', ru: '🚕 Можете ли вы помочь мне заказать такси?' },
